"use client"

import * as React from "react"
import { CircleAlert, CircleCheck, TriangleAlert, WandSparkles } from "lucide-react"

import { cn } from "@/lib/utils"
import { applyEnvFix, fixAllEnv, isSafeFix, parseEnv, type EnvIssue, type EnvTarget } from "@/registry/default/env-paste/parse-env"

export { applyEnvFix, fixAllEnv, parseEnv, toEnvKey, type EnvEntry, type EnvIssue, type EnvTarget } from "@/registry/default/env-paste/parse-env"

const SECRET_KEY = /SECRET|TOKEN|PASSWORD|PASSWD|PRIVATE|_KEY$|^KEY$|DSN|CREDENTIAL/

/** Keeps the prefix that tells test from live (`sk_test_…x9`) and hides the rest. */
export function maskSecret(value: string) {
  if (value.length <= 8) return "•".repeat(value.length)
  const prefix = value.match(/^["'`]?[a-z]+_(?:test|live)_/i)?.[0] ?? value.slice(0, 3)
  return `${prefix}${"•".repeat(4)}${value.slice(-2)}`
}

const fixClass = (severity: EnvIssue["severity"]) =>
  cn(
    "inline-flex min-h-6 max-w-full items-center gap-1 rounded-md border px-2 text-left font-medium transition-colors outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50",
    severity === "error"
      ? "border-red-500/40 text-red-800 hover:bg-red-500/10 dark:text-red-200"
      : "border-amber-500/40 text-amber-900 hover:bg-amber-500/10 dark:text-amber-200",
  )

export interface EnvPasteProps extends Omit<React.ComponentProps<"textarea">, "value" | "defaultValue" | "onChange"> {
  /** Visible label. */
  label?: string
  /** The environment this config is for. Enables test-key-in-production and live-key-in-development checks. */
  environment?: EnvTarget
  /** Controlled text. */
  value?: string
  /** Initial text when uncontrolled. */
  defaultValue?: string
  /** Called with the new text on every edit or fix. */
  onValueChange?: (value: string) => void
  /** Mask values whose key looks secret (keeps the sk_test_ / sk_live_ prefix visible). */
  maskSecrets?: boolean
  /** Label of the button that applies every safe fix. `{count}` is filled in. */
  fixAllLabel?: string
  /** Shown when every line parses cleanly. `{count}` is the number of variables. */
  cleanText?: string
  /** Shown when there are problems. `{errors}` and `{warnings}` are filled in. */
  problemsText?: string
  /** Placeholder shown in the empty textarea. */
  placeholder?: string
}

/**
 * A textarea for pasting .env / KEY=VALUE config that shows what the loader
 * will actually read. It flags stray and curly quotes, padded values, a ` #`
 * that silently cuts a value short, duplicate keys (naming the line that
 * wins), bad or lowercase keys, empty values, and test or live secrets in the
 * wrong environment, each with a one-tap fix where one is safe.
 */
export function EnvPaste({
  label = "Environment variables",
  environment,
  value,
  defaultValue = "",
  onValueChange,
  maskSecrets = true,
  fixAllLabel = "Fix {count}",
  cleanText = "{count} variables, no problems found.",
  problemsText = "{errors} errors, {warnings} warnings",
  placeholder = "Paste your .env here\nDATABASE_URL=postgres://…",
  rows = 8,
  id,
  className,
  ref,
  ...props
}: EnvPasteProps) {
  const [inner, setInner] = React.useState(defaultValue)
  const textareaRef = React.useRef<HTMLTextAreaElement>(null)
  const autoId = React.useId()
  const inputId = id ?? autoId
  const text = value ?? inner
  const entries = React.useMemo(() => parseEnv(text, environment), [text, environment])
  React.useImperativeHandle(ref, () => textareaRef.current as HTMLTextAreaElement)

  const update = (next: string) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }
  const issues = entries.flatMap((entry) => entry.issues)
  const errors = issues.filter((issue) => issue.severity === "error").length
  const safe = issues.filter(isSafeFix).length
  const masked = (key: string) => maskSecrets && SECRET_KEY.test(key)

  /** Selects the source line in the textarea so the user sees exactly what is meant. */
  const reveal = (line: number) => {
    const el = textareaRef.current
    if (!el) return
    const starts = text.split("\n").reduce<number[]>((acc, row) => [...acc, acc[acc.length - 1] + row.length + 1], [0])
    el.focus()
    el.setSelectionRange(starts[line], starts[line + 1] - 1)
  }

  return (
    <div data-slot="env-paste" className={cn("grid w-full max-w-xl gap-1.5", className)}>
      <div className="flex items-center justify-between gap-2">
        <label htmlFor={inputId} className="text-sm font-medium">
          {label}
        </label>
        {environment && (
          <span className={cn("rounded-md border px-1.5 py-0.5 font-mono text-xs", environment === "production" ? "border-red-500/40 text-red-700 dark:text-red-300" : "text-muted-foreground")}>
            {environment}
          </span>
        )}
      </div>
      <textarea
        ref={textareaRef}
        id={inputId}
        rows={rows}
        value={text}
        onChange={(event) => update(event.target.value)}
        spellCheck={false}
        autoCapitalize="none"
        autoCorrect="off"
        wrap="off"
        placeholder={placeholder}
        aria-invalid={errors > 0 || undefined}
        className="w-full min-w-0 resize-y rounded-md border bg-transparent px-3 py-2 font-mono text-xs leading-5 shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive dark:bg-input/30"
        {...props}
      />
      <div aria-live="polite" className="mt-1.5 flex min-h-6 items-center justify-between gap-2 text-xs">
        {!entries.length ? null : issues.length ? (
          <>
            <span className="flex items-center gap-1.5 text-muted-foreground">
              <TriangleAlert aria-hidden className="size-3.5 text-amber-600 dark:text-amber-400" />
              {problemsText.replace("{errors}", String(errors)).replace("{warnings}", String(issues.length - errors))}
            </span>
            {safe > 0 && (
              <button type="button" onClick={() => update(fixAllEnv(text, environment))} className={fixClass("warning")}>
                <WandSparkles aria-hidden className="size-3.5" />
                {fixAllLabel.replace("{count}", String(safe))}
              </button>
            )}
          </>
        ) : (
          <span className="flex items-center gap-1.5 text-emerald-700 dark:text-emerald-400">
            <CircleCheck aria-hidden className="size-3.5" />
            {cleanText.replace("{count}", String(entries.length))}
          </span>
        )}
      </div>
      {entries.length > 0 && (
        <ul aria-label="Parsed variables, as the loader will read them" className="divide-y overflow-hidden rounded-md border text-xs">
          {entries.map((entry) => (
            <li key={entry.line} data-issues={entry.issues.length || undefined} className="flex gap-2 px-2 py-1.5 data-issues:bg-amber-500/5">
              <button type="button" onClick={() => reveal(entry.line)} aria-label={`Select line ${entry.line + 1}`} className="h-5 w-5 shrink-0 rounded text-right font-mono text-muted-foreground tabular-nums hover:text-foreground outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50">
                {entry.line + 1}
              </button>
              <div className="min-w-0 flex-1">
                <div className="flex h-5 min-w-0 items-center gap-2 font-mono">
                  <span className="max-w-[60%] shrink-0 truncate font-medium">{entry.key}</span>
                  <span className="min-w-0 truncate text-muted-foreground" title={masked(entry.key) ? undefined : entry.value}>
                    {entry.value === "" ? <span className="opacity-60">(empty)</span> : masked(entry.key) ? maskSecret(entry.value) : entry.value}
                  </span>
                </div>
                {entry.issues.map((issue, index) => (
                  <p key={index} className={cn("mt-1 flex gap-1.5", issue.severity === "error" ? "text-red-700 dark:text-red-400" : "text-amber-700 dark:text-amber-400")}>
                    <span className="flex h-6 shrink-0 items-center">
                      {issue.severity === "error" ? <CircleAlert aria-hidden className="size-3.5" /> : <TriangleAlert aria-hidden className="size-3.5" />}
                    </span>
                    <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
                      <span className="py-1">{issue.message}</span>
                      {issue.fix !== undefined && (
                        <button type="button" onClick={() => update(applyEnvFix(text, entry.line, issue.fix ?? null))} className={fixClass(issue.severity)}>
                          {issue.fixLabel}
                        </button>
                      )}
                    </span>
                  </p>
                ))}
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

/** The environment a pasted .env is meant for. */
export type EnvTarget = "production" | "staging" | "development" | "test"

export interface EnvIssue {
  /** Stable kind, handy for tests and analytics. */
  kind: "invalid-key" | "lowercase-key" | "spaced-equals" | "stray-quote" | "smart-quote" | "whitespace" | "hash" | "empty" | "duplicate" | "wrong-env" | "not-assignment"
  /** Errors break the file; warnings are probably a mistake. */
  severity: "error" | "warning"
  message: string
  /** The corrected line, `null` to delete it, or `undefined` when there is no safe fix. */
  fix?: string | null
  fixLabel?: string
}

export interface EnvEntry {
  /** 0-based line index in the pasted text. */
  line: number
  key: string
  /** The value as a dotenv loader would read it. */
  value: string
  issues: EnvIssue[]
}

const KEY = /^[A-Za-z_][A-Za-z0-9_]*$/
const SMART = /[“”„‟″‘’‚‛′]/
const TEST_SECRET = /\b(?:sk|pk|rk|whsec)_test_|\brzp_test_|\bpk_test_|\bAKIA[A-Z0-9]*TEST/
const LIVE_SECRET = /\b(?:sk|rk)_live_|\brzp_live_/
const LOCAL_URL = /:\/\/(?:localhost|127\.0\.0\.1|0\.0\.0\.0)\b/

/** Turns `api-key.v2` into `API_KEY_V2` and `2FA` into `_2FA`. */
export function toEnvKey(key: string) {
  const clean = key.trim().replace(/[^A-Za-z0-9_]+/g, "_").toUpperCase()
  return /^[0-9]/.test(clean) ? `_${clean}` : clean || "_"
}

/** Strips one pair of matching quotes the way dotenv does. */
function unquote(raw: string) {
  const match = raw.match(/^(["'`])([\s\S]*)\1$/)
  return match ? match[2] : raw
}

/**
 * Parses KEY=VALUE text line by line and lists every slip a loader would
 * silently accept: stray or smart quotes, padded values, an unquoted ` #` that
 * cuts the value short, duplicate keys (the last one wins), bad key names,
 * empty values and test or live secrets in the wrong environment.
 */
export function parseEnv(text: string, environment?: EnvTarget): EnvEntry[] {
  const lines = text.split(/\r?\n/)
  const entries: EnvEntry[] = []
  lines.forEach((source, line) => {
    const trimmed = source.trimStart()
    if (!trimmed.trim() || trimmed.startsWith("#")) return
    const issues: EnvIssue[] = []
    const body = trimmed.replace(/^export\s+/, "")
    const prefix = body === trimmed ? "" : "export "
    const eq = body.indexOf("=")
    if (eq < 1) {
      entries.push({ line, key: trimmed.trim().slice(0, 40), value: "", issues: [{ kind: "not-assignment", severity: "error", message: "Not a KEY=VALUE line.", fix: null, fixLabel: "Remove line" }] })
      return
    }
    const rawKey = body.slice(0, eq)
    let rawValue = body.slice(eq + 1)
    const key = rawKey.trim()
    const rebuild = (k: string, v: string) => `${prefix}${k}=${v}`

    if (rawKey !== key || /^\s/.test(rawValue)) {
      issues.push({ kind: "spaced-equals", severity: "warning", message: "Spaces around = break shell and Docker loaders.", fix: rebuild(key, rawValue.trim()), fixLabel: "Remove spaces" })
      rawValue = rawValue.trimStart()
    }
    if (!KEY.test(key)) {
      issues.push({ kind: "invalid-key", severity: "error", message: "Keys allow only A–Z, 0–9 and _.", fix: rebuild(toEnvKey(key), rawValue), fixLabel: `Rename to ${toEnvKey(key)}` })
    } else if (/[a-z]/.test(key)) {
      issues.push({ kind: "lowercase-key", severity: "warning", message: "Lowercase key; code usually reads uppercase.", fix: rebuild(key.toUpperCase(), rawValue), fixLabel: `Use ${key.toUpperCase()}` })
    }

    const value = rawValue.trim()
    const opener = value[0]
    const quoted = /^(["'`]).*\1$/s.test(value) && value.length > 1
    if (SMART.test(value)) {
      issues.push({ kind: "smart-quote", severity: "error", message: "Curly quotes from a doc or chat end up in the value.", fix: rebuild(key, value.replace(/[“”„‟″]/g, '"').replace(/[‘’‚‛′]/g, "'")), fixLabel: "Use straight quotes" })
    } else if (/^["'`]/.test(value) && !quoted) {
      issues.push({ kind: "stray-quote", severity: "error", message: `Unclosed ${opener} becomes part of the value.`, fix: rebuild(key, value.slice(1).replace(/["'`]$/, "")), fixLabel: "Remove stray quote" })
    } else if (!quoted && /["']$/.test(value) && value.split(value.slice(-1)).length === 2) {
      issues.push({ kind: "stray-quote", severity: "error", message: "Unopened quote becomes part of the value.", fix: rebuild(key, value.slice(0, -1)), fixLabel: "Remove stray quote" })
    } else if (/^(["'])\1.+\1\1$/.test(value)) {
      issues.push({ kind: "stray-quote", severity: "error", message: "Quoted twice; one pair stays in the value.", fix: rebuild(key, value.slice(1, -1)), fixLabel: "Remove extra quotes" })
    } else if (!quoted && rawValue !== value && value) {
      issues.push({ kind: "whitespace", severity: "warning", message: "Trailing spaces: Docker keeps them, dotenv doesn't.", fix: rebuild(key, value), fixLabel: "Trim spaces" })
    } else if (quoted && unquote(value) !== unquote(value).trim()) {
      issues.push({ kind: "whitespace", severity: "warning", message: "Spaces inside the quotes are kept in the value.", fix: rebuild(key, `${opener}${unquote(value).trim()}${opener}`), fixLabel: "Trim inside quotes" })
    }

    let parsed = quoted ? unquote(value) : value
    const hash = !quoted ? value.search(/\s#/) : -1
    if (hash > 0) {
      parsed = value.slice(0, hash).trim()
      issues.push({ kind: "hash", severity: "warning", message: `" #" starts a comment: value is cut to "${parsed}".`, fix: rebuild(key, `"${value}"`), fixLabel: "Wrap in quotes" })
    }
    if (!parsed && !issues.some((issue) => issue.severity === "error")) {
      issues.push({ kind: "empty", severity: "warning", message: "Empty value; most code treats it as unset." })
    }
    if ((environment === "production" || environment === "staging") && TEST_SECRET.test(parsed)) {
      issues.push({ kind: "wrong-env", severity: "error", message: `Test key in ${environment}: nothing really charges.` })
    } else if ((environment === "development" || environment === "test") && LIVE_SECRET.test(parsed)) {
      issues.push({ kind: "wrong-env", severity: "error", message: `Live key in ${environment}: tests move real money.` })
    } else if (environment === "production" && LOCAL_URL.test(parsed)) {
      issues.push({ kind: "wrong-env", severity: "warning", message: "Points at localhost on a production server." })
    }
    entries.push({ line, key: KEY.test(key) ? key : toEnvKey(key), value: parsed, issues })
  })

  // Duplicates: every earlier definition is silently overridden by the last one.
  const last = new Map(entries.map((entry) => [entry.key, entry.line]))
  for (const entry of entries) {
    const winner = last.get(entry.key)
    if (winner !== undefined && winner !== entry.line) {
      entry.issues.unshift({ kind: "duplicate", severity: "warning", message: `Ignored: line ${winner + 1} sets it again and wins.`, fix: null, fixLabel: "Remove this line" })
    }
  }
  return entries
}

/** Replaces (or with `null`, deletes) one line of the text. */
export function applyEnvFix(text: string, line: number, fix: string | null) {
  const lines = text.split(/\r?\n/)
  if (fix === null) lines.splice(line, 1)
  else lines[line] = fix
  return lines.join("\n")
}

/** Fixes that can't change what the author meant. A ` #` or a non-assignment line needs a human. */
export const isSafeFix = (issue: EnvIssue) => issue.fix !== undefined && issue.kind !== "hash" && issue.kind !== "not-assignment"

/** Applies every safe fix, bottom-up so line numbers stay valid, until nothing changes. */
export function fixAllEnv(text: string, environment?: EnvTarget) {
  let current = text
  for (let pass = 0; pass < 5; pass++) {
    const fixable = parseEnv(current, environment).filter((entry) => entry.issues.some(isSafeFix))
    if (!fixable.length) break
    for (const entry of [...fixable].reverse()) {
      const issue = entry.issues.find(isSafeFix)
      if (issue) current = applyEnvFix(current, entry.line, issue.fix ?? null)
    }
  }
  return current
}
